effect.shader:
mat2 rotate2d(float angle){
return mat2(cos(angle), -sin(angle),
sin(angle), cos(angle));
}
void main() {
vec2 uv = acLayerNorm;
uv -= 0.5;
uv.x *= acLayerSize.x / acLayerSize.y;
float time = acTime;
float zoom = exp(time * zoomSpeed);
float angle = time * rotationSpeed;
uv = rotate2d(angle) * uv;
uv *= zoom;
uv.x += sin(uv.y * warpFrequency + time * 0.5) * warpAmount;
uv.y += cos(uv.x * warpFrequency - time * 0.3) * warpAmount;
vec2 grid = fract(uv * gridSize);
float lineWidth = 0.05;
float lineX = step(1.0 - lineWidth, grid.x) + step(lineWidth, grid.x) * step(grid.x, lineWidth);
float lineY = step(1.0 - lineWidth, grid.y) + step(lineWidth, grid.y) * step(grid.y, lineWidth);
float isGridLine = min(lineX + lineY, 1.0);
vec3 finalColor = mix(bgColor.rgb, gridColor.rgb, isGridLine);
gl_FragColor = vec4(finalColor, 1.0);
}
